// Simplified from Apache Log4j2 message formatting, pre-2.15.
public void logRequest(HttpServletRequest req) {
    String ua = req.getHeader("User-Agent");
    logger.info("request from {} ua={}", req.getRemoteAddr(), ua);
}

// Inside the logging pipeline, the formatted message is scanned for
// ${...} expressions and each is resolved by a lookup (jndi, env, ...).
static String render(String formatted) {
    return StrSubstitutor.replace(formatted);   // expands ${jndi:...}
}
